payload.command:
cd …/dcmp_on_s7b/workspace && python3 - <<'PYEOF'
import json, collections
rows = [json.loads(l) for l in open("adapters/g1/practice_rows.jsonl")]
print("rows:", len(rows))
from collections import Counter
# per-task stage completion by step (last step)
by_step_task = collections.defaultdict(lambda: collections.defaultdict(list))
for r in rows:
    by_step_task[r["step"]][r["task"]].append(r)
for step in sorted(by_step_task):
    for task in sorted(by_step_task[step]):
        rs = by_step_task[step][task]
        stage_names = []
        for r in rs:
            for k in (r.get("stages") or {}):
                if k not in stage_names: stage_names.append(k)
        comp = {k: sum(1 for r in rs if (r.get("stages") or {}).get(k)) for k in stage_names}
        comp = {k: f"{v}/{len(rs)}" for k,v in comp.items()}
        print(f"step {step} {task}: reward>0 frac={sum(1 for r in rs if r.get('reward',0)>0)/len(rs):.2f} maxr={max(r.get('reward',0) for r in rs):.4f} {comp}")
# best rows
best = sorted(rows, key=lambda r: r.get("reward",0), reverse=True)[:3]
for r in best:
    print("BEST", r["task"], r["seed"], r.get("reward"), r.get("stages"), "rc", r.get("sandbox_rc"), "secs", r.get("secs"))
PYEOF

