cd …/dcmp_on_s7b/workspace && python3 - <<'PYEOF'
import json
rows = [json.loads(l) for l in open("adapters/g1/practice_rows.jsonl")]
rs = [r for r in rows if r["task"]=="restack" and r["step"]==8]
n_close = sum(1 for r in rs if "close_gripper()" in r["program"])
n_plan = sum(1 for r in rs if "plan_grasp" in r["program"])
n_fence = sum(1 for r in rs if "```" in r["program"])
n_solve = sum(1 for r in rs if "solve_ik" in r["program"])
n_move = sum(1 for r in rs if "move_to_joints" in r["program"])
print(f"step8 restack n={len(rs)}: close_gripper={n_close} plan_grasp={n_plan} fence={n_fence} solve_ik={n_solve} move_to_joints={n_move}")
# trace: min gripper opening during episode
def min_open(r):
    tr = r.get("trace") or {}
    if isinstance(tr, dict):
        tr = tr.get("frames") or list(tr.values())
    if isinstance(tr, list):
        vals = []
        for f in tr:
            if isinstance(f, dict):
                g = (f.get("grippers") or {}).get("arm0") or {}
                if "opening" in g: vals.append(g["opening"])
                elif "gripper" in f and isinstance(f["gripper"], dict) and "opening" in f["gripper"]: vals.append(f["gripper"]["opening"])
        return min(vals) if vals else None
    return None
import collections
mo = [min_open(r) for r in rs]
print("min opening over episode (None=unknown trace format):", [f"{x:.3f}" if x is not None else "?" for x in mo[:15]])
# inspect trace structure
r0 = rs[0]
tr = r0.get("trace")
print("trace type:", type(tr), "len:", len(tr) if tr else 0)
if isinstance(tr, dict):
    print("trace keys:", list(tr.keys())[:10])
    v = list(tr.values())
    if v: print("sample value:", json.dumps(v[0])[:400])
elif isinstance(tr, list) and tr:
    print("sample:", json.dumps(tr[0])[:400])
PYEOF

