import math

def _final(r):
    return r.get("final_state") or {}

def _init_z(r, name):
    o = (_final(r).get("objects") or {}).get(name) or {}
    ip = o.get("init_pos")
    return float(ip[2]) if ip else None

def _final_z(r, name):
    o = (_final(r).get("objects") or {}).get(name) or {}
    p = o.get("pos")
    return float(p[2]) if p else None

def _final_xy(r, name):
    o = (_final(r).get("objects") or {}).get(name) or {}
    p = o.get("pos")
    return (float(p[0]), float(p[1])) if p else None

def _maxz(r, name):
    # max z the object reached: over trace points and the final pos
    zmax = None
    pts = (r.get("trace") or {}).get("points") or []
    for p in pts:
        o = ((p.get("objects") or {}).get(name) or {})
        pos = o.get("pos")
        if pos is not None:
            try:
                z = float(pos[2])
                if zmax is None or z > zmax: zmax = z
            except Exception:
                pass
    fz = _final_z(r, name)
    if fz is not None and (zmax is None or fz > zmax):
        zmax = fz
    return zmax

def _shaped(r):
    try:
        return float(r.get("reward") or 0.0)
    except Exception:
        return 0.0

def _lifted(r, name, thresh=0.04):
    iz = _init_z(r, name)
    mz = _maxz(r, name)
    if mz is None or iz is None:
        return False
    return (mz - iz) > thresh

def _aligned(r, above, base):
    az = _final_z(r, above); bz = _final_z(r, base)
    axy = _final_xy(r, above); bxy = _final_xy(r, base)
    if None in (az, bz, axy, bxy):
        return False
    dz = az - bz
    dxy = math.hypot(axy[0]-bxy[0], axy[1]-bxy[1])
    return (dz > 0.02) and (dxy < 0.06)

def reward(r):
    if r.get("task_completed"):
        return 1.0
    task = r.get("task", "")
    sh = _shaped(r)
    if task == "restack":
        # suppress the cheap "shove the green off the red" component
        stages = r.get("stages") or {}
        if stages.get("unstack the green off the red"):
            sh *= 0.3
        lifted = 1.0 if _lifted(r, "red_cube") else 0.0
        aligned = 1.0 if _aligned(r, "red_cube", "green_cube") else 0.0
        return min(1.0, 0.25 * sh + 0.5 * lifted + 0.25 * aligned)
    if task == "revstack":
        lifted = 1.0 if _lifted(r, "green_cube") else 0.0
        aligned = 1.0 if _aligned(r, "green_cube", "red_cube") else 0.0
        return min(1.0, 0.25 * sh + 0.5 * lifted + 0.25 * aligned)
    if task == "nut":
        stages = r.get("stages") or {}
        if stages.get("insert the nut"): return 0.95
        if stages.get("align the nut over the peg"): return 0.75
        if stages.get("grasp the nut"): return 0.5
        if stages.get("reach the handle"): return 0.25
        return max(0.0, 0.15 * sh)
    return max(0.0, sh)
